package rw.schoolpass.web;
import com.google.zxing.*; import com.google.zxing.client.j2se.MatrixToImageWriter; import com.google.zxing.common.BitMatrix; import org.springframework.http.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import rw.schoolpass.repo.StudentRepository; import java.io.*;
@Controller public class CardController {private final StudentRepository repo; public CardController(StudentRepository r){repo=r;}
 @GetMapping("/students/{id}/card") String card(@PathVariable Long id,Model m){m.addAttribute("student",repo.findById(id).orElseThrow());return "cards/student-card";}
 @GetMapping(value="/students/{id}/qr",produces=MediaType.IMAGE_PNG_VALUE) ResponseEntity<byte[]> qr(@PathVariable Long id)throws Exception{var s=repo.findById(id).orElseThrow();if(!s.isCardActive())return ResponseEntity.status(409).build();BitMatrix matrix=new MultiFormatWriter().encode(s.getCardToken(),BarcodeFormat.QR_CODE,360,360);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(matrix,"PNG",out);return ResponseEntity.ok().contentType(MediaType.IMAGE_PNG).body(out.toByteArray());}}
